Here is the commit message:
ntfs3: fix integer overflow in run_unpack() volume boundary
 check

The volume boundary check `lcn + len > sbi->used.bitmap.nbits` uses raw
addition which can wrap around for large lcn and len values, bypassing
the validation.  Use check_add_overflow() as is already done for the
adjacent prev_lcn + dlcn and vcn64 + len checks added by commit
3ac37e100385 ("ntfs3: Fix integer overflow in run_unpack()").

Found by fuzzing with a source-patched harness (LibAFL + QEMU).

Fixes: 82cae269cfa95 ("fs/ntfs3: Add initialization of super block")
Cc: stable@vger.kernel.org
Signed-off-by: Tobias Gaertner <tob.gaertner@me.com>
Signed-off-by: Konstantin Komarov <almaz.alexandrovich@paragon-software.com>

Here is the root cause:
Integer overflow in the addition `lcn + len` within the volume boundary check in `run_unpack()`. When `lcn` and `len` are large, their sum can wrap around (overflow) to a small value, causing the subsequent comparison `lcn + len > sbi->used.bitmap.nbits` to be false even though the actual range exceeds the volume. This bypasses the intended validation and can lead to out-of-bounds access or other memory corruption.

Here is the patch:
  */
 int run_unpack(struct runs_tree *run, struct ntfs_sb_info *sbi, CLST ino,
 	       CLST svcn, CLST evcn, CLST vcn, const u8 *run_buf,
 	       int run_buf_size)
 {
 	u64 prev_lcn, vcn64, lcn, next_vcn;
 	const u8 *run_last, *run_0;
 	bool is_mft = ino == MFT_REC_MFT;

 	if (run_buf_size < 0)
 		return -EINVAL;

 	/* Check for empty. */
 	if (evcn + 1 == svcn)
 		return 0;

 	if (evcn < svcn)
 		return -EINVAL;

 	run_0 = run_buf;
 	run_last = run_buf + run_buf_size;
 	prev_lcn = 0;
 	vcn64 = svcn;

 	/* Read all runs the chain. */
 	/* size_size - How much bytes is packed len. */
 	while (run_buf < run_last) {
 		/* size_size - How much bytes is packed len. */
 		u8 size_size = *run_buf & 0xF;
 		/* offset_size - How much bytes is packed dlcn. */
 		u8 offset_size = *run_buf++ >> 4;
 		u64 len;

 		if (!size_size)
 			break;

 		/*
 		 * Unpack runs.
 		 * NOTE: Runs are stored little endian order
 		 * "len" is unsigned value, "dlcn" is signed.
 		 * Large positive number requires to store 5 bytes
 		 * e.g.: 05 FF 7E FF FF 00 00 00
 		 */
 		if (size_size > sizeof(len))
 			return -EINVAL;

 		if (run_buf + size_size > run_last)
 			return -EINVAL;

 		len = run_unpack_s64(run_buf, size_size, 0);
 		/* Skip size_size. */
 		run_buf += size_size;

 		if (!len)
 			return -EINVAL;

 		if (!offset_size)
 			lcn = SPARSE_LCN64;
 		else if (offset_size <= sizeof(s64)) {
 			s64 dlcn;

 			if (run_buf + offset_size > run_last)
 				return -EINVAL;

 			/* Initial value of dlcn is -1 or 0. */
 			dlcn = (run_buf[offset_size - 1] & 0x80) ? (s64)-1 : 0;
 			dlcn = run_unpack_s64(run_buf, offset_size, dlcn);
 			/* Skip offset_size. */
 			run_buf += offset_size;

 			if (!dlcn)
 				return -EINVAL;

 			/* Check special combination: 0 + SPARSE_LCN64. */
 			if (!prev_lcn && dlcn == SPARSE_LCN64) {
 				lcn = SPARSE_LCN64;
 			} else if (check_add_overflow(prev_lcn, dlcn, &lcn)) {
 				return -EINVAL;
 			}
 			prev_lcn = lcn;
 		} else {
 			/* The size of 'dlcn' can't be > 8. */
 			return -EINVAL;
 		}

 		if (check_add_overflow(vcn64, len, &next_vcn))
 			return -EINVAL;

 		/* Check boundary. */
 		if (next_vcn > evcn + 1)
 			return -EINVAL;

 #ifndef CONFIG_NTFS3_64BIT_CLUSTER
 		if (next_vcn > 0x100000000ull || (lcn + len) > 0x100000000ull) {
 			ntfs_err(
 				sbi->sb,
 				"This driver is compiled without CONFIG_NTFS3_64BIT_CLUSTER (like windows driver).\n"
 				"Volume contains 64 bits run: vcn %llx, lcn %llx, len %llx.\n"
 				"Activate CONFIG_NTFS3_64BIT_CLUSTER to process this case",
 				vcn64, lcn, len);
 			return -EOPNOTSUPP;
 		}
 #endif
-		if (lcn != SPARSE_LCN64 && lcn + len > sbi->used.bitmap.nbits) {
-			/* LCN range is out of volume. */
-			return -EINVAL;
+		if (lcn != SPARSE_LCN64) {
+			u64 lcn_end;
+
+			if (check_add_overflow(lcn, len, &lcn_end))
+				return -EINVAL;
+			if (lcn_end > sbi->used.bitmap.nbits) {
+				/* LCN range is out of volume. */
+				return -EINVAL;
+			}
 		}

 		if (!run)
 			; /* Called from check_attr(fslog.c) to check run. */
 		else if (run == RUN_DEALLOCATE) {
 			/*
 			 * Called from ni_delete_all to free clusters
 			 * without storing in run.
 			 */
 			if (lcn != SPARSE_LCN64)
 				mark_as_free_ex(sbi, lcn, len, true);
 		} else if (vcn64 >= vcn) {
 			if (!run_add_entry(run, vcn64, lcn, len, is_mft))
 				return -ENOMEM;
 		} else if (next_vcn > vcn) {
 			u64 dlen = vcn - vcn64;

 			if (!run_add_entry(run, vcn, lcn + dlen, len - dlen,
 					   is_mft))
 				return -ENOMEM;
 		}

 		vcn64 = next_vcn;
 	}

 	if (vcn64 != evcn + 1) {
 		/* Not expected length of unpacked runs. */
 		return -EINVAL;
 	}

 	return run_buf - run_0;
 }



